from torch import nn as _archcanvas_nn

class _ArchCanvasCustomModule(_archcanvas_nn.Module):
    def __init__(self):
        super().__init__()
        self.inner = MaskedAttention(embed_dim=32, num_heads=4, dropout=0.1, batch_first=True)
        self.output = _archcanvas_nn.Identity()

    def forward(self, query, key, value, attn_mask):
        result = self.inner(query=query, key=key, value=value, attn_mask=attn_mask)
        return {'output': self.output(result[0])}
